        // The Python profiles are the authority: each `_PROFILES` entry declares its
        // own `code=`, so scraping those is a direct read of the source of truth
        // rather than a second list to keep in step.
        const profiles = source.slice(source.indexOf('_PROFILES: dict[str, DocLanguage]'));
        const body = profiles.slice(0, profiles.indexOf('\n}\n'));
        const codes = [...body.matchAll(/code="([^"]+)"/g)].map(m => m[1]);

        expect(codes.length).toBeGreaterThan(1);
        expect(DOC_LANGUAGE_CHOICES.map(c => c.code).sort()).toEqual(codes.sort());
    });

    it('keeps English first so the default reads as the default', () => {
        expect(DOC_LANGUAGE_CHOICES[0].code).toBe('en');
    });
});

import * as vscode from 'vscode';
import * as fsSync from 'fs';
import * as path from 'path';
import { languageName } from '../webview/doc-lang';

export const CONFIG_FILENAME = 'config.json';

/**
 * The tree's authoring language for the payload, read from `.codoc/config.json`.
 *
 * Reads the CONFIG and not the sidecar, which matters more than it looks. The
 * sidecar's copy is written by the daemon, so a switch made in the webview landed in
 * config.json while the immediate repost still read the daemon's older sidecar — the
 * button wrote the right thing and appeared to do nothing, and with no daemon
 * running it never caught up at all. The config file is the authored state and the
 * only thing that answers this question without waiting on another process.
 *
 * `sidecarCode` is the fallback for a workspace whose config predates this feature
 * (or was deleted), and 'en' behind that — which is what every tree was before the
 * setting existed. Synchronous because `buildPayload` is, and this is one small
 * file read per repaint.
 */
export function readDocLanguage(
    codocDirFsPath: string,
    sidecarCode?: string,
): { code: string; name: string } {
    let code = '';
    try {
        const raw = fsSync.readFileSync(path.join(codocDirFsPath, CONFIG_FILENAME), 'utf-8');
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed.doc_language === 'string') code = parsed.doc_language.trim();
    } catch {
        // Missing or malformed: fall through to the sidecar / default, exactly as
        // doclang.read_config does. A hand-mangled settings file must not break the
        // editor.
    }
    const resolved = code || sidecarCode || 'en';
    return { code: resolved, name: languageName(resolved) };
}

